<?php
declare(strict_types=1);
require_once __DIR__.'/../src/audience_store.php';
require_once __DIR__.'/../src/audience_collection_render.php';
function contentSecurityPolicyNonce():string{return 'collectionTestNonce123456';}
$checks=0;
$expect=static function(bool $ok,string $label)use(&$checks):void{if(!$ok)throw new RuntimeException($label);++$checks;};
$reject=static function(callable $call)use($expect):void{try{$call();}catch(InvalidArgumentException){$expect(true,'Invalid document rejected');return;}throw new RuntimeException('Expected rejection');};
foreach(AUDIENCE_COLLECTION_KINDS as$kind){
    $blank=audienceCollectionDefaults($kind);$blank['title']='   ';
    $blank=audienceCollectionDocument($blank,$kind,[],[],[]);
    $expect($blank['title']==='','A blank heading stays empty when saving '.$kind);
    $expect(audienceCollectionDocument($blank,$kind,[],[],[])['title']==='','A blank heading survives reloading '.$kind);
    foreach([false,true]as$preview)$expect(!str_contains(audienceCollectionHtml(['kind'=>$kind,'document'=>$blank],[],[],'','',[],'','',null,$preview),'<h1>'),'Blank headings render without fallback text in '.$kind);
    foreach(['button','thanks','permission']as$key)$reject(fn()=>audienceCollectionDocument(array_replace($blank,[$key=>'']),$kind,[],[],[]));
}
$doc=audienceCollectionDefaults('hosted');
$doc['language']='he';$doc['messages']['error_title']='בדקו את התשובה';$doc['messages']['invalid']='נא למלא את השדות';
$doc['advanced']=['enabled'=>true,'pages'=>['signup'=>'<section style="padding:20px" onclick="bad()"><script>bad()</script><h2>{{title}}</h2>{{message}}{{form}}</section>']];
$canonical=audienceCollectionDocument($doc,'hosted',[],[],[]);
$expect(!str_contains($canonical['advanced']['pages']['signup'],'script')&&!str_contains($canonical['advanced']['pages']['signup'],'onclick'),'Advanced source strips active content');
$resource=['kind'=>'hosted','document'=>$canonical];
$html=audienceCollectionHtml($resource,[],[],'/native-action','sealed-proof',[],'Original internal validation');
$blocked=audienceCollectionHtml($resource,[],[],'/native-action','sealed-proof',[],'','',null,false,'Signup temporarily unavailable');
$expect(str_contains($blocked,'<fieldset disabled>')&&str_contains($blocked,'Signup temporarily unavailable'),'Custom page layouts retain disabled native controls and delivery availability');
$editorNonce='editorPageNonce1234567890';
$livePreview=audienceCollectionHtml($resource,[],[],'','',[],'','',null,true,'',$editorNonce);
preg_match_all('/<style nonce="([^"]+)"/',$livePreview,$previewStyles);
$expect(count($previewStyles[1])>=2&&array_unique($previewStyles[1])===[$editorNonce],'AJAX preview and custom layout CSS use the containing editor nonce');
$public=audienceCollectionHtml($resource,[],[],'','',[],'','',null,false,'',$editorNonce);
$expect(str_contains($public,'nonce="collectionTestNonce123456"')&&!str_contains($public,$editorNonce),'Public rendering keeps its own response nonce');
$reject(fn()=>audienceCollectionHtml($resource,[],[],'','',[],'','',null,true,'','invalid" nonce'));
$expect(str_contains($livePreview,'class="trap" hidden aria-hidden="true"'),'The spam trap stays hidden even if preview CSS fails');
$expect(str_contains($html,'dir="rtl"')&&str_contains($html,'בדקו את התשובה'),'Language and translated error heading reach the public page');
$expect(str_contains($html,'נא למלא את השדות')&&!str_contains($html,'Original internal validation'),'Public error copy is editable without leaking internal errors');
$expect(str_contains($html,'sealed-proof')&&str_contains($html,'action="/native-action"')&&str_contains($html,'name="permission"'),'Custom layouts retain native proof, destination and explicit permission');
$expect(str_contains($html,'button:hover,.button:hover{filter:brightness(.9);text-decoration:none}')&&str_contains($html,'button:focus-visible,a:focus-visible{outline:3px solid #007c89')&&str_contains($html,'nonce="collectionTestNonce123456"'),'Public controls retain visible hover and keyboard focus in nonce-scoped styles');
$expect(!str_contains($html,'<script')&&!str_contains($html,'rel="stylesheet"'),'Branded public forms and previews do not load MOED shell scripts or styles');
$expect(str_contains($html,'appearance:none')&&str_contains($html,'select:dir(rtl)'),'Branded forms share native dropdown sizing and right-to-left arrow placement');
$expect(!str_contains($html,' style="')&&str_contains($html,'padding:20px'),'Custom CSS is nonce authorized');
$preview=audienceCollectionHtml($resource,[],[],'','',[],'','',null,true);
$expect(str_contains($preview,'<button disabled>'),'Custom preview cannot submit');
foreach(['{{form}}','{{content}}{{form}}{{message}}','<img alt="{{content}}" src="https://example.test/a.png">','<script>{{content}}</script>']as$source)$reject(fn()=>audienceCollectionAdvancedHtml($source));
$expect(audienceCollectionAdvancedHtml('<a href="javascript:bad()">Bad</a>{{content}}')==='Bad{{content}}','Unsafe links cannot escape the native page');
$reject(fn()=>audienceCollectionDocument(array_replace($doc,['advanced'=>['pages'=>['signup'=>str_repeat('x',60001)]]]),'hosted',[],[],[]));
$survey=audienceCollectionDefaults('survey');$survey['questions']=[['id'=>'choice','label'=>'Choose','type'=>'dropdown','required'=>true,'options'=>['One','Two'],'other'=>true,'answer_tags'=>['One'=>[7]]]];
$survey=audienceCollectionDocument($survey,'survey',[],[],[['id'=>7]]);
$expect(audienceCollectionAnswers($survey,['answers'=>['choice'=>'One']])===['choice'=>'One'],'Dropdown choices validate');
$expect(audienceCollectionAnswers($survey,['answers'=>['choice'=>'__message_monkey_other__'],'answers_other'=>['choice'=>'An alternative']])===['choice'=>'Other: An alternative'],'Other choices require and retain typed answers');
$reject(fn()=>audienceCollectionAnswers($survey,['answers'=>['choice'=>'forged']]));
$reject(fn()=>audienceCollectionAnswers($survey,['answers'=>['choice'=>'__message_monkey_other__']]));
$reject(fn()=>audienceCollectionDocument($survey,'survey',[],[],[]));
$survey['messages']['choose']='Choisissez';$survey['messages']['other']='Autre';
$surveyHtml=audienceCollectionHtml(['kind'=>'survey','document'=>$survey],[],[],'','');
$expect(str_contains($surveyHtml,'Choisissez')&&str_contains($surveyHtml,'Autre'),'Dropdown and Other option labels use translations');
$checkbox=$survey;$checkbox['questions'][0]['type']='checkboxes';
$expect(audienceCollectionAnswers($checkbox,['answers'=>['choice'=>['One','__message_monkey_other__']],'answers_other'=>['choice'=>'Something else']])===['choice'=>['One','Other: Something else']],'Checkbox Other preserves both authored and typed choices');
$reject(fn()=>audienceCollectionDocument(array_replace($survey,['close_at'=>'2026-02-30T12:00']),'survey',[],[],[['id'=>7]]));
$brandFont='data:font/ttf;base64,'.base64_encode("\x00\x01\x00\x00".str_repeat("\0",44));
$landing=audienceCollectionDefaults('landing');$landing['font']='Tahoma';$landing['web_font']=$brandFont;$landing['web_font_name']='Example Light';
$landing=audienceCollectionDocument($landing,'landing',[],[],[]);
$expect($landing['web_font']===$brandFont&&$landing['web_font_name']==='Example Light'&&$landing['font']==='Tahoma','Landing page retains a validated uploaded font and its fallback');
$brandedHtml=audienceCollectionHtml(['kind'=>'landing','document'=>$landing],[],[],'','');
$expect(str_contains($brandedHtml,'@font-face{font-family:MOEDCollectionBrandFont;src:url('.$brandFont.')')&&str_contains($brandedHtml,'--collection-font:MOEDCollectionBrandFont,Tahoma'),'Uploaded font is embedded in preview and public CSS');
foreach(['Arial','Georgia','Verdana','Tahoma','Times New Roman']as$font)$expect(audienceCollectionDocument(array_replace($landing,['font'=>$font]),'landing',[],[],[])['font']===$font,'Brand Kit fallback fonts are preserved');
$reject(fn()=>audienceCollectionDocument(array_replace($landing,['web_font'=>'https://example.test/font.woff2']),'landing',[],[],[]));
$reject(fn()=>audienceCollectionDocument(array_replace($landing,['web_font'=>'data:font/ttf;base64,'.base64_encode('bad-font')]),'landing',[],[],[]));
$systemFont=audienceCollectionDocument(array_replace($landing,['web_font'=>'']),'landing',[],[],[]);
$expect($systemFont['web_font_name']===''&&!str_contains(audienceCollectionHtml(['kind'=>'landing','document'=>$systemFont],[],[],'',''),'@font-face'),'Selecting a system font removes embedded font metadata and CSS');
$logo='data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
$logoDocument=audienceCollectionDocument(array_replace($landing,['logo'=>$logo]),'landing',[],[],[]);
$expect($logoDocument['logo']===$logo&&str_contains(audienceCollectionHtml(['kind'=>'landing','document'=>$logoDocument],[],[],'',''),'src="'.$logo.'"'),'Brand Kit GIF logos remain valid in landing page snapshots and public pages');
$reject(fn()=>audienceCollectionDocument(array_replace($landing,['logo'=>'data:image/png;base64,YmFkLWltYWdl']),'landing',[],[],[]));
$sizedLogo=audienceCollectionDocument(array_replace($logoDocument,['logo_width'=>360]),'landing',[],[],[]);
$expect($sizedLogo['logo_width']===360&&str_contains(audienceCollectionHtml(['kind'=>'landing','document'=>$sizedLogo],[],[],'',''),'--collection-logo-width:360px;--collection-logo-height:none'),'Landing page logo width reaches public and preview rendering without a fixed height');
foreach([0,1201,'invalid']as$invalidWidth)$reject(fn()=>audienceCollectionDocument(array_replace($logoDocument,['logo_width'=>$invalidWidth]),'landing',[],[],[]));
$preferenceLogo=audienceCollectionDocument(array_replace(audienceCollectionDefaults('preferences'),['logo'=>$logo,'logo_width'=>320,'logo_resized'=>true]),'preferences',[],[],[]);
$expect($preferenceLogo['logo_resized']&&str_contains(audienceCollectionHtml(['kind'=>'preferences','document'=>$preferenceLogo],[],[],'',''),'--collection-logo-width:320px;--collection-logo-height:none'),'Resized preference logos retain their width on public forms');
$preferenceLogo['logo_resized']=false;
$expect(!str_contains(audienceCollectionHtml(['kind'=>'preferences','document'=>$preferenceLogo],[],[],'',''),'--collection-logo-width:'),'Existing preference logos retain their original automatic sizing');
$imageDocument=audienceCollectionDocument(array_replace($preferenceLogo,['sections'=>[['type'=>'image','url'=>$logo,'text'=>'Content image','width'=>180]]]),'preferences',[],[],[]);
$imageHtml=audienceCollectionHtml(['kind'=>'preferences','document'=>$imageDocument],[],[],'','');
$expect($imageDocument['sections'][0]['width']===180&&str_contains($imageHtml,'class="section-image" width="180"'),'Content image width persists through validation and public rendering');
$expect(!str_contains($imageHtml,' style="')&&!str_contains($imageHtml,'collection-image-resize'),'Published images do not expose editor tools or inline styles');
foreach([0,-1,1201,'invalid']as$invalidWidth){$invalid=$imageDocument;$invalid['sections'][0]['width']=$invalidWidth;$reject(fn()=>audienceCollectionDocument($invalid,'preferences',[],[],[]));}
$imageDocument['sections'][0]['width']='';
$expect(!isset(audienceCollectionDocument($imageDocument,'preferences',[],[],[])['sections'][0]['width']),'Automatic content image width remains supported');
$legacyFooter=audienceCollectionDefaults('hosted');unset($legacyFooter['show_footer']);
$expect(audienceCollectionDocument($legacyFooter,'hosted',[],[],[])['show_footer']===true,'Existing forms keep their footer credit by default');
foreach(['hosted','popup','landing','survey','preferences']as$kind){
    $footer=audienceCollectionDefaults($kind);$footer['messages']['powered']="Our community <script>alert(1)</script> & friends\nStay connected";
    $footer=audienceCollectionDocument($footer,$kind,[],[],[]);
    $publicFooter=audienceCollectionHtml(['kind'=>$kind,'document'=>$footer],[],[],'','');
    $expect(str_contains($publicFooter,'Our community &lt;script&gt;alert(1)&lt;/script&gt; &amp; friends'."\nStay connected")&&!str_contains($publicFooter,'<script>'),'Custom footer text is escaped and keeps line breaks');
    $previewFooter=audienceCollectionHtml(['kind'=>$kind,'document'=>$footer],[],[],'','',[],'','',null,true);
    $expect(str_contains($previewFooter,'class="collection-footer-credit"')&&str_contains($previewFooter,'Preview — submissions are disabled.'),'Preview displays the footer credit and a separate disabled-submission notice');
    $footer['show_footer']=false;$footer['messages']['powered']='';
    $footer=audienceCollectionDocument($footer,$kind,[],[],[]);
    $expect(!str_contains(audienceCollectionHtml(['kind'=>$kind,'document'=>$footer],[],[],'',''),'<small class="collection-footer-credit">'),'Hidden credit is absent from published form markup');
    $footer['show_footer']=true;
    $reject(fn()=>audienceCollectionDocument($footer,$kind,[],[],[]));
}
foreach(['false',0,null,[]]as$invalidFooter)$reject(fn()=>audienceCollectionDocument(array_replace($legacyFooter,['show_footer'=>$invalidFooter]),'hosted',[],[],[]));
$editorFields=[['id'=>1,'label'=>'Full Name'],['id'=>2,'label'=>'Date of Entry'],['id'=>3,'label'=>'Fund'],['id'=>4,'label'=>'Phone Number'],['id'=>5,'label'=>'  FULL NAME  ']];
$expect(array_column(audienceCollectionEditorFields($editorFields),'id')===[4],'Form choices omit record-only fields and retain other audience fields');
$expect(count($editorFields)===5,'Filtering form choices leaves the audience field records intact');
echo "Collection customization: $checks checks passed.\n";
